//! Bind address and token authentication.
//!
//! The console can run a governed cycle and drive hardware, so it is a control
//! surface, not a dashboard. Two rules follow from that:
//!
//! 1. **Loopback by default.** Reaching it from another machine should be a
//!    deliberate act (an SSH tunnel, or an explicit bind), never the default.
//! 2. **A non-loopback bind requires a token.** Widening the listener without
//!    authentication is refused at startup rather than warned about, because a
//!    warning in a log nobody reads is not a control.
//! 3. **Watching and driving are separate capabilities.** A second, independent
//!    read-only token grants telemetry and the witness chain but carries no
//!    control authority. Giving someone a dashboard should not hand them the
//!    ability to run cycles and drive hardware.
//!
//! The capability split follows the admission model in `cognitum-one/cognitum-media`
//! (ADR-0004, admitted streaming audio): *independent* capabilities rather than
//! one scoped down, because a derived listener token is one bug away from being
//! a control token.

use std::net::{IpAddr, SocketAddr};

/// What a caller is allowed to do.
///
/// Ordered: `Control` strictly exceeds `Listen`. Deliberately NOT a bitfield —
/// a capability set invites "listen plus a bit of control", which is how a
/// read-only credential quietly acquires authority.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Capability {
    /// May read telemetry, devices and the witness chain. Nothing else.
    Listen,
    /// May additionally run cycles and drive hardware.
    Control,
}

/// Why the server refused to start.
#[derive(Debug, PartialEq, Eq)]
pub enum BindError {
    /// A non-loopback bind was requested with no token configured.
    ExposedWithoutToken(IpAddr),
    /// A read-only token was configured without a control token, which would
    /// leave writes unauthenticated while implying separation exists.
    ReadTokenWithoutControlToken,
    /// The address could not be parsed.
    BadAddress(String),
}

impl std::fmt::Display for BindError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::ExposedWithoutToken(ip) => write!(
                f,
                "refusing to bind {ip} without authentication: this console can run \
                 cycles and drive hardware. Set RULTRA_UI_TOKEN, or bind loopback \
                 and reach it over an SSH tunnel."
            ),
            Self::ReadTokenWithoutControlToken => write!(
                f,
                "RULTRA_UI_READ_TOKEN is set but RULTRA_UI_TOKEN is not: that would \
                 leave cycles and hardware control unauthenticated while implying a \
                 read-only tier exists. Set both, or neither."
            ),
            Self::BadAddress(s) => write!(f, "could not parse bind address {s:?}"),
        }
    }
}

impl std::error::Error for BindError {}

/// Resolve the listen address, refusing an unauthenticated public bind and an
/// incoherent token configuration.
pub fn resolve_bind(
    host: &str,
    port: u16,
    control: Option<&str>,
    read: Option<&str>,
) -> Result<SocketAddr, BindError> {
    let ip: IpAddr = host
        .parse()
        .map_err(|_| BindError::BadAddress(host.to_string()))?;
    if read.is_some() && control.is_none() {
        return Err(BindError::ReadTokenWithoutControlToken);
    }
    if !ip.is_loopback() && control.is_none() {
        return Err(BindError::ExposedWithoutToken(ip));
    }
    Ok(SocketAddr::new(ip, port))
}

/// What capability a request needs.
///
/// Anything that changes the world needs `Control`. Reading does not. The split
/// is by effect, not by convenience: a GET that ran a cycle would be a GET that
/// needs Control, and the right fix would be to stop it being a GET.
pub fn required_for(method: &str, path: &str) -> Capability {
    if method.eq_ignore_ascii_case("GET") || method.eq_ignore_ascii_case("HEAD") {
        Capability::Listen
    } else {
        let _ = path;
        Capability::Control
    }
}

/// Does a request from the loopback interface get read-only access without a
/// token?
///
/// **Off by default, and deliberately opt-in.** The desktop app on the box
/// needs to render telemetry without handling a credential, but enabling that
/// silently would change the security posture of every deployment that merely
/// upgraded. The appliance turns it on explicitly; the library never assumes it.
///
/// It grants `Listen` only. Control still requires the token, because "already
/// on the box" is a reason to let someone watch, not a reason to let them drive
/// the hardware. Peer addresses come from the accepted socket, so a remote
/// client cannot claim to be loopback.
pub fn local_listen_enabled(env: Option<&str>) -> bool {
    matches!(env, Some("1") | Some("true") | Some("yes"))
}

/// May a loopback caller **drive the hardware** without a token?
///
/// The stricter sibling of [`local_listen_enabled`], and off by default for a
/// stronger reason: watching is passive, driving is not. A box that grants this
/// lets anything running on it — any user, any process, any page a browser on
/// the box happens to load — run cycles and move actuators.
///
/// It exists because the alternative on an appliance is worse in practice. The
/// operator standing at the CrowPi cannot read the token: it lives in a
/// root-only env file or a cloud secret, so the console in front of them asks
/// for a credential they cannot produce, and the usual answer is to paste the
/// token into the browser — which leaves it in a session store for anything
/// on the box to read anyway. Making the grant explicit is more honest than
/// pretending a token protects a machine whose console is physically present.
///
/// Still opt-in, still per-deployment, and never implied by `LOCAL_LISTEN`.
pub fn local_control_enabled(env: Option<&str>) -> bool {
    matches!(env, Some("1") | Some("true") | Some("yes"))
}

/// Which capability the presented credential carries, if any.
///
/// The control token is checked first so that a deployment which accidentally
/// sets both variables to the same value grants control rather than silently
/// downgrading the operator to read-only.
pub fn capability<'a>(
    control: Option<&str>,
    read: Option<&str>,
    peer_loopback: bool,
    local_listen: bool,
    local_control: bool,
    get: impl Fn(&str) -> Option<&'a str>,
) -> Option<Capability> {
    // No control token is only reachable on loopback — resolve_bind guarantees
    // it — so a local request is intended and fully authorized.
    let Some(control) = control else {
        return Some(Capability::Control);
    };
    // A presented credential is judged on its own merits first, so a local
    // caller holding the control token still gets Control rather than being
    // capped at the loopback grant.
    if let Some(presented) = presented(get) {
        if secret_eq(presented, control) {
            return Some(Capability::Control);
        }
        if let Some(read) = read {
            if secret_eq(presented, read) {
                return Some(Capability::Listen);
            }
        }
        // A wrong token is a wrong token even from loopback: falling through to
        // the local grant would make a bad credential indistinguishable from
        // none, and hide a misconfigured client.
        return None;
    }
    // Control before Listen: a deployment that enables both means the stronger
    // one, and silently capping it at Listen would be a confusing downgrade.
    if peer_loopback && local_control {
        return Some(Capability::Control);
    }
    if peer_loopback && local_listen {
        return Some(Capability::Listen);
    }
    None
}

/// Compare two secrets without leaking their relationship through timing.
///
/// Length is compared first and separately, which does leak length — that is
/// accepted and standard; the value is what must not leak byte by byte.
pub fn secret_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

/// Extract a presented token from an `Authorization: Bearer` header, falling
/// back to an `X-Rultra-Token` header.
///
/// Deliberately does **not** read a query parameter: a token in a URL lands in
/// server logs, browser history and `Referer` headers.
pub fn presented<'a>(get: impl Fn(&str) -> Option<&'a str>) -> Option<&'a str> {
    if let Some(v) = get("authorization") {
        if let Some(rest) = v
            .strip_prefix("Bearer ")
            .or_else(|| v.strip_prefix("bearer "))
        {
            return Some(rest.trim());
        }
    }
    get("x-rultra-token").map(str::trim)
}

/// Is this request allowed?
#[allow(clippy::too_many_arguments)]
pub fn authorized<'a>(
    control: Option<&str>,
    read: Option<&str>,
    peer_loopback: bool,
    local_listen: bool,
    local_control: bool,
    method: &str,
    path: &str,
    get: impl Fn(&str) -> Option<&'a str>,
) -> bool {
    match capability(
        control,
        read,
        peer_loopback,
        local_listen,
        local_control,
        get,
    ) {
        Some(held) => held >= required_for(method, path),
        None => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Calls `authorized` with the loopback grant OFF, which is the default and
    /// what almost every test wants to assert against.
    fn ok<'a>(
        c: Option<&str>,
        r: Option<&str>,
        m: &str,
        path: &str,
        g: impl Fn(&str) -> Option<&'a str>,
    ) -> bool {
        authorized(c, r, false, false, false, m, path, g)
    }

    fn none(_: &str) -> Option<&'static str> {
        None
    }
    fn bearer(tok: &'static str) -> impl Fn(&str) -> Option<&'static str> {
        move |k: &str| {
            (k == "authorization")
                .then_some(Box::leak(format!("Bearer {tok}").into_boxed_str()) as &'static str)
        }
    }

    #[test]
    fn loopback_needs_no_token() {
        assert!(resolve_bind("127.0.0.1", 17880, None, None).is_ok());
        assert!(resolve_bind("::1", 17880, None, None).is_ok());
    }

    /// The rule that matters: widening the listener without a token is refused
    /// at startup, not warned about.
    #[test]
    fn a_public_bind_without_a_token_is_refused() {
        let e = resolve_bind("0.0.0.0", 17880, None, None).unwrap_err();
        assert!(matches!(e, BindError::ExposedWithoutToken(_)));
        assert!(
            e.to_string().contains("RULTRA_UI_TOKEN"),
            "must say how to fix it"
        );
    }

    #[test]
    fn a_public_bind_with_a_token_is_allowed() {
        assert!(resolve_bind("0.0.0.0", 17880, Some("s3cret"), None).is_ok());
    }

    /// A read token with no control token implies a separation that does not
    /// exist: writes would be unauthenticated. Refuse rather than mislead.
    #[test]
    fn a_read_token_without_a_control_token_is_refused() {
        assert_eq!(
            resolve_bind("127.0.0.1", 17880, None, Some("ro")).unwrap_err(),
            BindError::ReadTokenWithoutControlToken
        );
    }

    #[test]
    fn a_bad_address_is_rejected() {
        assert_eq!(
            resolve_bind("not-an-ip", 1, None, None).unwrap_err(),
            BindError::BadAddress("not-an-ip".into())
        );
    }

    #[test]
    fn secret_eq_matches_only_identical_values() {
        assert!(secret_eq("abc", "abc"));
        assert!(!secret_eq("abc", "abd"));
        assert!(!secret_eq("abc", "abcd"));
        assert!(secret_eq("", ""));
    }

    #[test]
    fn bearer_token_is_extracted_case_insensitively() {
        assert_eq!(
            presented(|k| (k == "authorization").then_some("Bearer tok")),
            Some("tok")
        );
        assert_eq!(
            presented(|k| (k == "authorization").then_some("bearer tok")),
            Some("tok")
        );
    }

    #[test]
    fn the_fallback_header_works() {
        assert_eq!(
            presented(|k| (k == "x-rultra-token").then_some("tok")),
            Some("tok")
        );
    }

    /// A token in a query string leaks into logs, history and Referer headers.
    #[test]
    fn a_query_parameter_is_not_a_credential() {
        assert_eq!(presented(|k| (k == "token").then_some("tok")), None);
    }

    #[test]
    fn reads_need_listen_and_writes_need_control() {
        assert_eq!(required_for("GET", "/api/summary"), Capability::Listen);
        assert_eq!(required_for("HEAD", "/api/summary"), Capability::Listen);
        assert_eq!(required_for("POST", "/api/cycle"), Capability::Control);
        assert_eq!(required_for("DELETE", "/api/anything"), Capability::Control);
    }

    #[test]
    fn control_strictly_exceeds_listen() {
        assert!(Capability::Control > Capability::Listen);
    }

    #[test]
    fn without_a_control_token_everything_is_allowed() {
        assert!(ok(None, None, "POST", "/api/cycle", none));
    }

    #[test]
    fn the_control_token_may_read_and_write() {
        assert!(ok(Some("c"), Some("r"), "GET", "/api/summary", bearer("c")));
        assert!(ok(Some("c"), Some("r"), "POST", "/api/cycle", bearer("c")));
    }

    /// The point of the split: a listener can watch the box and cannot drive it.
    #[test]
    fn the_read_token_may_read_but_never_write() {
        assert!(ok(Some("c"), Some("r"), "GET", "/api/summary", bearer("r")));
        assert!(!ok(Some("c"), Some("r"), "POST", "/api/cycle", bearer("r")));
        assert!(!ok(
            Some("c"),
            Some("r"),
            "POST",
            "/api/matrix",
            bearer("r")
        ));
    }

    #[test]
    fn an_unknown_token_gets_nothing() {
        assert!(!ok(
            Some("c"),
            Some("r"),
            "GET",
            "/api/summary",
            bearer("nope")
        ));
        assert!(!ok(Some("c"), Some("r"), "POST", "/api/cycle", none));
    }

    /// If a deployment sets both variables to the same value, the operator must
    /// keep control rather than be silently downgraded to read-only.
    #[test]
    fn identical_tokens_resolve_to_control_not_listen() {
        assert_eq!(
            capability(
                Some("same"),
                Some("same"),
                false,
                false,
                false,
                bearer("same")
            ),
            Some(Capability::Control)
        );
    }

    #[test]
    fn a_malformed_authorization_header_does_not_pass() {
        assert!(!ok(Some("c"), None, "GET", "/api/s", |k| {
            (k == "authorization").then_some("c")
        }));
    }

    #[test]
    fn the_loopback_grant_is_off_unless_explicitly_enabled() {
        assert!(!local_listen_enabled(None));
        assert!(!local_listen_enabled(Some("0")));
        assert!(!local_listen_enabled(Some("")));
        assert!(local_listen_enabled(Some("1")));
        assert!(local_listen_enabled(Some("true")));
    }

    /// The desktop app's case: a local window renders telemetry with no
    /// credential at all.
    #[test]
    fn loopback_reads_without_a_token_when_enabled() {
        assert!(authorized(
            Some("c"),
            None,
            true,
            true,
            false,
            "GET",
            "/api/summary",
            none
        ));
    }

    /// "Already on the box" is a reason to let someone watch, not to let them
    /// drive the hardware.
    #[test]
    fn loopback_can_never_write_without_a_token() {
        assert!(!authorized(
            Some("c"),
            None,
            true,
            true,
            false,
            "POST",
            "/api/cycle",
            none
        ));
        assert!(!authorized(
            Some("c"),
            None,
            true,
            true,
            false,
            "POST",
            "/api/matrix",
            none
        ));
    }

    #[test]
    fn a_remote_peer_gets_nothing_even_when_the_grant_is_on() {
        assert!(!authorized(
            Some("c"),
            None,
            false,
            true,
            false,
            "GET",
            "/api/summary",
            none
        ));
    }

    #[test]
    fn loopback_without_the_grant_still_needs_a_token() {
        assert!(!authorized(
            Some("c"),
            None,
            true,
            false,
            false,
            "GET",
            "/api/summary",
            none
        ));
    }

    /// A local caller holding the control token keeps Control; the loopback
    /// grant must not cap them at read-only.
    #[test]
    fn the_loopback_grant_never_downgrades_a_real_credential() {
        assert_eq!(
            capability(Some("c"), None, true, true, false, bearer("c")),
            Some(Capability::Control)
        );
        assert!(authorized(
            Some("c"),
            None,
            true,
            true,
            false,
            "POST",
            "/api/cycle",
            bearer("c")
        ));
    }

    /// A wrong token is a wrong token even from loopback. Falling through to
    /// the grant would make a bad credential indistinguishable from none and
    /// hide a misconfigured client.
    #[test]
    fn a_wrong_token_from_loopback_is_refused_not_downgraded() {
        assert_eq!(
            capability(Some("c"), None, true, true, false, bearer("wrong")),
            None
        );
        assert!(!authorized(
            Some("c"),
            None,
            true,
            true,
            false,
            "GET",
            "/api/s",
            bearer("wrong")
        ));
    }
    /// The whole point: an operator physically at the box can drive it.
    #[test]
    fn loopback_controls_without_a_token_when_control_is_granted() {
        assert!(authorized(
            Some("c"),
            None,
            true,
            false,
            true,
            "POST",
            "/api/cycle",
            none
        ));
    }

    /// A remote caller gets nothing from it, ever. The peer address comes from
    /// the accepted socket, so this cannot be claimed by a header.
    #[test]
    fn a_remote_peer_never_gets_local_control() {
        assert!(!authorized(
            Some("c"),
            None,
            false,
            true,
            true,
            "POST",
            "/api/cycle",
            none
        ));
    }

    /// Granting control must not be reachable by accident: reads-only stays
    /// reads-only, and the two flags are independent.
    #[test]
    fn local_listen_alone_still_cannot_write() {
        assert!(!authorized(
            Some("c"),
            None,
            true,
            true,
            false,
            "POST",
            "/api/cycle",
            none
        ));
    }

    /// Off unless explicitly set, and a wrong value does not enable it.
    #[test]
    fn local_control_is_off_by_default() {
        assert!(!local_control_enabled(None));
        assert!(!local_control_enabled(Some("")));
        assert!(!local_control_enabled(Some("0")));
        assert!(!local_control_enabled(Some("maybe")));
        assert!(local_control_enabled(Some("1")));
        assert!(local_control_enabled(Some("true")));
    }

    /// A bad credential still loses, even with the grant on. Otherwise a
    /// misconfigured client would be indistinguishable from a working one.
    #[test]
    fn a_wrong_token_beats_the_local_grant() {
        assert_eq!(
            capability(Some("c"), None, true, true, true, bearer("wrong")),
            None
        );
    }
}

//! `rultra-mcp` — the box's sensors and capabilities over MCP.
//!
//! Exposes what the CLI and console already do, as tools an agent can call and
//! `ruv://` resources it can read, following the URI convention used by the
//! ruvnet federation gateway.
//!
//! # stdout is the protocol
//!
//! This is a stdio MCP server: stdout carries JSON-RPC frames and nothing else.
//! A stray `println!` anywhere in the process corrupts the stream and the
//! client disconnects with a parse error that points nowhere near the cause.
//! Diagnostics go to stderr, always.
#![forbid(unsafe_code)]

mod server;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    eprintln!("rultra-mcp: starting stdio server");
    server::run().await
}

//! HTTP handlers. Every response is derived from the real catalog, the real
//! buses, and the real witness chain on disk.

use crate::state;
use axum::{
    http::StatusCode,
    response::{Html, IntoResponse},
    Json,
};
use rultra_sense::{device, DeviceId, DeviceKind, Verification};
use rultra_witness::Chain;
use serde_json::{json, Value as J};

/// three.js, served from the binary.
///
/// Vendored rather than CDN-loaded: this is an appliance that may have no
/// internet, and a screensaver that fails offline is not a screensaver. The
/// console never loads it at startup — the client fetches it only when the
/// screensaver actually activates, so an idle feature costs nothing until it
/// is used.
pub async fn vendor_three() -> impl IntoResponse {
    (
        [
            (axum::http::header::CONTENT_TYPE, "application/javascript"),
            // Immutable: the file only changes when the binary does.
            (
                axum::http::header::CACHE_CONTROL,
                "public, max-age=31536000, immutable",
            ),
        ],
        include_str!("../ui/vendor/three.min.js"),
    )
}

pub async fn index() -> Html<&'static str> {
    // One definition, in the module that also structurally validates it — so
    // what ships is exactly what the tests checked.
    Html(crate::asset::INDEX)
}

fn verification_str(v: Verification) -> &'static str {
    match v {
        Verification::Working => "working",
        Verification::Unvalidated => "unvalidated",
        Verification::AcksButSilent => "acks_but_silent",
        Verification::Untested => "untested",
        Verification::Faulty => "faulty",
    }
}

/// Headline numbers for the overview.
pub async fn summary() -> Json<J> {
    let policy = state::applier().load();
    // One trip to the sensors for everything this endpoint needs, rather than
    // four separate locks and four chances to interleave with another request.
    // From the snapshot: no lock on the bus, no waiting on physics.
    let snap = state::latest();
    let responding = snap.presence.iter().filter(|p| p.responding).count();
    let temp = state::snap_scalar(&snap, DeviceId::CpuTemp);
    let lux = state::snap_scalar(&snap, DeviceId::Light);
    // Same rule the fusion applies: a condemned sensor publishes nothing.
    let range_verification = device::lookup(DeviceId::Range)
        .map(|d| d.verification)
        .unwrap_or(Verification::Untested);
    let range_cm = rultra_spatial::usable(
        state::snap_scalar(&snap, DeviceId::Range),
        range_verification,
    );
    let working = device::CATALOG
        .iter()
        .filter(|d| d.verification == Verification::Working)
        .count();

    // The fused band rather than raw centimetres: a band is what an
    // uncalibrated range finder can honestly support (ADR-0006). The range
    // finder is currently Faulty, so it contributes nothing at all and
    // proximity falls back to Empty rather than reporting a floating pin.
    let room = rultra_spatial::RoomState::fuse(
        range_cm.map(|cm| cm / 100.0),
        lux,
        range_verification,
        device::lookup(DeviceId::Light)
            .map(|d| d.verification)
            .unwrap_or(Verification::Untested),
        None,
    );
    let steering = rultra_spatial::Steering::from(&room);
    let ceiling = rultra_evolve::policy::THERMAL_CEILING_C;

    // Chain depth is a liveness signal: a console that claims the loop is
    // running should be able to point at entries proving it.
    let chain_len = std::fs::read_to_string(state::state_dir().join("witness.jsonl"))
        .map(|t| t.lines().filter(|l| !l.trim().is_empty()).count())
        .unwrap_or(0);

    Json(json!({
        "die_temp_c": temp,
        "thermal_ceiling_c": ceiling,
        "thermally_stressed": temp.map(|t| t >= ceiling).unwrap_or(false),
        "lux": lux,
        "poll_interval_ms": policy.poll_interval_ms,
        "policy_hash": policy.content_hash(),
        "devices_total": device::CATALOG.len(),
        "devices_responding": responding,
        "devices_working": working,
        "witness_entries": chain_len,
        "swept_at": snap.swept_at,
        "proximity": room.proximity,
        "light_band": room.light,
        "range_cm": range_cm,
        "steering": {
            "intensity": steering.intensity,
            "luminance": steering.luminance,
            "calm": steering.calm,
            "billable": steering.billable,
        },
    }))
}

/// The catalog joined with a live probe.
pub async fn devices() -> Json<J> {
    let presence = state::latest().presence;
    let items: Vec<J> = device::CATALOG
        .iter()
        .map(|d| {
            let p = presence.iter().find(|p| p.device == d.id);
            json!({
                "id": format!("{:?}", d.id).to_lowercase(),
                "part": d.part,
                "kind": match d.kind { DeviceKind::Sensor => "sensor", DeviceKind::Actuator => "actuator" },
                "bus": serde_json::to_value(&d.bus).unwrap_or(J::Null),
                "verification": verification_str(d.verification),
                "evidence": d.evidence,
                "responding": p.map(|p| p.responding).unwrap_or(false),
                "detail": p.map(|p| p.detail.clone()).unwrap_or_default(),
            })
        })
        .collect();
    Json(json!({ "devices": items }))
}

/// One reading from every sensor. The UI polls this; a websocket would be
/// more elegant but a poll survives a reconnect without extra machinery, which
/// matters more on a box that may be power-cycled.
pub async fn telemetry() -> Json<J> {
    let snap = state::latest();
    let readings: Vec<J> = {
        device::CATALOG
            .iter()
            .filter(|d| d.kind == DeviceKind::Sensor)
            .filter_map(|d| {
                let r = snap.readings.get(&d.id)?.clone();
                Some(json!({
                    "id": format!("{:?}", d.id).to_lowercase(),
                    "value": r.value,
                    // The measurement time, which may predate this response
                    // when the reading came from cache. Compare it to `at`
                    // below to see the true age.
                    "at": r.at,
                    "verification": verification_str(r.verification),
                }))
            })
            .collect()
    };
    Json(json!({ "readings": readings, "at": rultra_sense::now() }))
}

/// Is the box actually running cycles on its own, and what did it last decide?
///
/// "Self-optimizing" is only true if something runs the loop unattended. This
/// endpoint reports the real systemd timer state rather than assuming it, and
/// says plainly when no schedule is installed.
pub async fn schedule() -> Json<J> {
    let active = std::process::Command::new("systemctl")
        .args(["is-active", "rultra-cycle.timer"])
        .output()
        .ok()
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .unwrap_or_else(|| "unknown".into());

    // `systemctl list-timers` is the only place the *next* elapse is exposed.
    let next = std::process::Command::new("systemctl")
        .args([
            "list-timers",
            "rultra-cycle.timer",
            "--no-pager",
            "--no-legend",
        ])
        .output()
        .ok()
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .filter(|s| !s.is_empty());

    // Last decision, read from the chain rather than a separate status file —
    // one source of truth, and it cannot drift from the signed record.
    let mut last_decision = None;
    let mut last_reason = None;
    if let Ok(text) = std::fs::read_to_string(state::state_dir().join("witness.jsonl")) {
        if let Ok(entries) = Chain::parse_jsonl(&text) {
            // Walk backwards collecting both, and stop only when both are
            // found. Breaking on the decision alone always returned a null
            // reason, because `gated` is written BEFORE promoted/rolled_back
            // and so is reached later in a reverse scan.
            for e in entries.iter().rev() {
                let v = serde_json::to_value(&e.event).unwrap_or(J::Null);
                match v.get("event").and_then(|x| x.as_str()) {
                    Some(k @ ("promoted" | "rolled_back")) if last_decision.is_none() => {
                        last_decision = Some(k.to_string());
                    }
                    Some("gated") if last_reason.is_none() => {
                        last_reason = v.get("reason").and_then(|x| x.as_str()).map(str::to_string);
                    }
                    _ => {}
                }
                if last_decision.is_some() && last_reason.is_some() {
                    break;
                }
            }
        }
    }

    Json(json!({
        "timer_active": active == "active",
        "timer_state": active,
        "next_elapse": next,
        "last_decision": last_decision,
        "last_gate_reason": last_reason,
    }))
}

/// Which ruvnet tools are on this box, and what they report.
///
/// Probed, never declared. A tools page that lists what was *installed* drifts
/// the moment something is removed or stops; this asks each one.
pub async fn tools() -> Json<J> {
    let probe = |bin: &str, args: &[&str]| -> Option<String> {
        let out = std::process::Command::new(bin).args(args).output().ok()?;
        let t = String::from_utf8_lossy(&out.stdout);
        t.lines()
            .next()
            .map(|l| l.trim().to_string())
            .filter(|l| !l.is_empty())
    };
    // ruview's sensing server, which is the interesting one: it is a real
    // running service with its own honesty posture.
    let ruview_health = std::process::Command::new("curl")
        .args(["-s", "--max-time", "3", "http://127.0.0.1:3000/health"])
        .output()
        .ok()
        .and_then(|o| serde_json::from_slice::<J>(&o.stdout).ok());

    Json(json!({
        "tools": [
            { "id": "ruview", "role": "WiFi-DensePose sensing server and the claim-check honesty guardrail",
              "present": std::path::Path::new("/usr/bin/ruview").exists(),
              "endpoint": "http://127.0.0.1:3000",
              "health": ruview_health,
              // Surfaced deliberately: ruview labels its own data source, and
              // a consumer that hides that label is worse than one that never
              // had it.
              "source_note": "ruview reports its own data source; `simulated` means it is not live radio" },
            { "id": "ruvector", "role": "vector memory, HNSW, RVF containers",
              // Resolved through the global npm root: `npx --no-install` does
              // not find globally installed packages, so probing that way
              // under-reported a tool that is present. A tools page that
              // under-reports is as wrong as one that over-reports.
              "present": probe("npm", &["root", "-g"])
                  .map(|root| std::path::Path::new(&root).join("@ruvector/cli").exists())
                  .unwrap_or(false) },
            { "id": "ruflo", "role": "swarm orchestration, memory, hooks",
              "present": std::path::Path::new("/usr/local/bin/ruflo").exists() },
            { "id": "ruv-swarm", "role": "multi-agent coordination",
              "present": std::path::Path::new("/usr/bin/ruv-swarm").exists() },
            { "id": "agentdb", "role": "agent memory with vector embeddings",
              "present": std::path::Path::new("/usr/bin/agentdb").exists() },
            { "id": "rultra-mcp", "role": "this box's sensors as MCP tools and ruv:// resources",
              "present": std::path::Path::new("/usr/local/bin/rultra-mcp").exists() },
        ]
    }))
}

/// Lint this box's own accuracy claims with `ruview claim-check`.
///
/// The device catalog's evidence strings are accuracy claims about hardware,
/// and this project has spent its whole life insisting those be honest. Running
/// someone else's linter over them is the only way to find out whether that
/// discipline actually holds, rather than whether it *feels* like it holds.
pub async fn claimcheck() -> Json<J> {
    let mut results = Vec::new();
    let mut failed = 0usize;
    for d in device::CATALOG {
        let out = std::process::Command::new("ruview")
            .args(["claim-check", "--text", d.evidence])
            .output();
        let verdict = match out {
            Ok(o) => serde_json::from_slice::<J>(&o.stdout).unwrap_or_else(
                |_| json!({ "ok": null, "summary": "claim-check produced no JSON" }),
            ),
            Err(e) => json!({ "ok": null, "summary": format!("ruview unavailable: {e}") }),
        };
        if verdict.get("ok") == Some(&J::Bool(false)) {
            failed += 1;
        }
        results.push(json!({
            "device": format!("{:?}", d.id).to_lowercase(),
            "verification": verification_str(d.verification),
            "verdict": verdict,
        }));
    }
    Json(json!({ "checked": results.len(), "flagged": failed, "results": results }))
}

pub async fn policy() -> Json<J> {
