/// The box, as an MCP server.
#[derive(Clone)]
pub struct RultraMcp {
    // Read by the code #[tool_handler] generates, which clippy cannot see.
    #[allow(dead_code)]
    tool_router: ToolRouter<RultraMcp>,
}

#[tool_router]
impl RultraMcp {
    pub fn new() -> Self {
        Self {
            tool_router: Self::tool_router(),
        }
    }

    fn ok(v: J) -> Result<CallToolResult, McpError> {
        Ok(CallToolResult::success(vec![ContentBlock::text(
            serde_json::to_string_pretty(&v).unwrap_or_else(|_| "{}".into()),
        )]))
    }

    #[tool(
        description = "Every device on the board with how well each is actually known to work. Verification is a claim about evidence: only \"working\" means someone observed correct output.",
        annotations(
            read_only_hint = true,
            destructive_hint = false,
            idempotent_hint = true
        )
    )]
    async fn rultra_devices(&self) -> Result<CallToolResult, McpError> {
        Self::ok(devices_doc())
    }

    #[tool(
        description = "One reading from every sensor that answers right now.",
        annotations(
            read_only_hint = true,
            destructive_hint = false,
            idempotent_hint = false
        )
    )]
    async fn rultra_telemetry(&self) -> Result<CallToolResult, McpError> {
        Self::ok(telemetry_doc())
    }

    #[tool(
        description = "Read one device by id. Errors rather than fabricating a value when the device does not answer.",
        annotations(
            read_only_hint = true,
            destructive_hint = false,
            idempotent_hint = false
        )
    )]
    async fn rultra_read(
        &self,
        Parameters(a): Parameters<ReadArgs>,
    ) -> Result<CallToolResult, McpError> {
        let want = a.device.to_lowercase();
        let Some(d) = device::CATALOG
            .iter()
            .find(|d| format!("{:?}", d.id).to_lowercase() == want)
        else {
            return Err(McpError::invalid_params(
                format!("unknown device: {want}"),
                None,
            ));
        };
        match backend().read(d.id) {
            Ok(r) => Self::ok(json!({ "id": want, "value": r.value, "at": r.at,
                                      "verification": verification_str(r.verification) })),
            Err(e) => Err(McpError::internal_error(e.to_string(), None)),
        }
    }

    #[tool(
        description = "Fused room state (proximity and light as bands) plus the normalized media steering signal.",
        annotations(
            read_only_hint = true,
            destructive_hint = false,
            idempotent_hint = false
        )
    )]
    async fn rultra_spatial(&self) -> Result<CallToolResult, McpError> {
        Self::ok(spatial_doc())
    }

    #[tool(
        description = "The signed, hash-chained record of every decision the box has made.",
        annotations(
            read_only_hint = true,
            destructive_hint = false,
            idempotent_hint = true
        )
    )]
    async fn rultra_witness(
        &self,
        Parameters(a): Parameters<WitnessArgs>,
    ) -> Result<CallToolResult, McpError> {
        Self::ok(witness_doc(a.limit.unwrap_or(20).min(500) as usize))
    }

    #[tool(
        description = "What this box can sense and actuate, derived from the catalog rather than declared.",
        annotations(
            read_only_hint = true,
            destructive_hint = false,
            idempotent_hint = true
        )
    )]
    async fn rultra_capabilities(&self) -> Result<CallToolResult, McpError> {
        Self::ok(capabilities_doc())
    }

    #[tool(
        description = "Run one governed cycle: observe, propose, gate, promote or roll back. May change the sensing policy, and always appends to the witness chain.",
        annotations(
            read_only_hint = false,
            destructive_hint = false,
            idempotent_hint = false
        )
    )]
    async fn rultra_cycle(&self) -> Result<CallToolResult, McpError> {
        let out = std::process::Command::new("rultra")
            .arg("cycle")
            .arg("8")
            .output();
        match out {
            Ok(o) if o.status.success() => Self::ok(
                serde_json::from_slice(&o.stdout)
                    .unwrap_or_else(|_| json!({"raw": String::from_utf8_lossy(&o.stdout)})),
            ),
            Ok(o) => Err(McpError::internal_error(
                String::from_utf8_lossy(&o.stderr).to_string(),
                None,
            )),
            Err(e) => Err(McpError::internal_error(
                format!("rultra binary unavailable: {e}"),
                None,
            )),
        }
    }

    #[tool(
        description = "Draw on the 8x8 LED matrix: heart, clear, or scroll text.",
        annotations(
            read_only_hint = false,
            destructive_hint = false,
            idempotent_hint = true
        )
    )]
    async fn rultra_matrix(
        &self,
        Parameters(a): Parameters<MatrixArgs>,
    ) -> Result<CallToolResult, McpError> {
        #[cfg(all(target_os = "linux", feature = "hardware"))]
        {
            use rultra_sense::backend::linux::LinuxBackend;
            const HEART: [u8; 8] = [0x00, 0x66, 0xff, 0xff, 0xff, 0x7e, 0x3c, 0x18];
            let r = match a.pattern.as_str() {
                "heart" => LinuxBackend::matrix_draw(&HEART),
                "clear" => LinuxBackend::matrix_draw(&[0; 8]),
                "scroll" => LinuxBackend::matrix_scroll(a.text.as_deref().unwrap_or("RULTRA"), 60),
                other => {
                    return Err(McpError::invalid_params(
                        format!("unknown pattern: {other}"),
                        None,
                    ))
                }
            };
            return match r {
                Ok(()) => Self::ok(json!({ "ok": true, "pattern": a.pattern })),
                Err(e) => Err(McpError::internal_error(e.to_string(), None)),
            };
        }
        #[cfg(not(all(target_os = "linux", feature = "hardware")))]
        {
            let _ = a;
            Err(McpError::internal_error(
                "built without the hardware feature".to_string(),
                None,
            ))
        }
    }

    #[tool(
        description = "Write up to two 16-character lines to the character LCD.",
        annotations(
            read_only_hint = false,
            destructive_hint = false,
            idempotent_hint = true
        )
    )]
    async fn rultra_lcd(
        &self,
        Parameters(a): Parameters<LcdArgs>,
    ) -> Result<CallToolResult, McpError> {
        #[cfg(all(target_os = "linux", feature = "hardware"))]
        {
            use rultra_sense::backend::linux::LinuxBackend;
            let b =
                LinuxBackend::open().map_err(|e| McpError::internal_error(e.to_string(), None))?;
            return match b.lcd_write(&a.line1, a.line2.as_deref().unwrap_or("")) {
                Ok(()) => Self::ok(json!({ "ok": true })),
                Err(e) => Err(McpError::internal_error(e.to_string(), None)),
            };
        }
        #[cfg(not(all(target_os = "linux", feature = "hardware")))]
        {
            let _ = a;
            Err(McpError::internal_error(
                "built without the hardware feature".to_string(),
                None,
            ))
        }
    }
}

impl Default for RultraMcp {
    fn default() -> Self {
        Self::new()
    }
}

#[tool_handler]
impl ServerHandler for RultraMcp {
    fn get_info(&self) -> ServerInfo {
        ServerInfo::new(
            ServerCapabilities::builder()
                .enable_tools()
                .enable_resources()
                .build(),
        )
        .with_server_info(Implementation::from_build_env())
        .with_instructions(
            "rultra MCP — the sensors, actuators, governed loop and witness chain of a \
             CrowPi/Raspberry Pi 5 box. Read ruv://rultra/{devices,telemetry,spatial,policy,\
             witness,capabilities}. Verification is load-bearing: only \"working\" means a \
             device was observed producing correct output, \"unvalidated\" means its output \
             is stable but never checked against a reference, and \"acks_but_silent\" means \
             it answers its bus while producing no observable effect. Do not present an \
             unvalidated reading as a measurement.",
        )
    }

    async fn list_resources(
        &self,
        _p: Option<PaginatedRequestParams>,
        _c: RequestContext<RoleServer>,
    ) -> Result<ListResourcesResult, McpError> {
        Ok(ListResourcesResult::with_all_items(
            RES.iter()
                .map(|(uri, name, desc)| {
                    let mut r = Resource::new(*uri, *name);
                    r.description = Some((*desc).to_string());
                    r.mime_type = Some("application/json".to_string());
                    r
                })
                .collect(),
        ))
    }

    async fn read_resource(
        &self,
        p: ReadResourceRequestParams,
        _c: RequestContext<RoleServer>,
    ) -> Result<ReadResourceResponse, McpError> {
        let doc = match p.uri.as_str() {
            "ruv://rultra/devices" => devices_doc(),
            "ruv://rultra/telemetry" => telemetry_doc(),
            "ruv://rultra/spatial" => spatial_doc(),
            "ruv://rultra/policy" => policy_doc(),
            "ruv://rultra/witness" => witness_doc(50),
            "ruv://rultra/capabilities" => capabilities_doc(),
            other => {
                return Err(McpError::resource_not_found(
                    format!("unknown resource: {other}"),
                    None,
                ))
            }
        };
        Ok(ReadResourceResult::new(vec![ResourceContents::text(
            serde_json::to_string_pretty(&doc).unwrap_or_else(|_| "{}".into()),
            p.uri,
        )])
        .into())
    }
}

/// Serve on stdio.
pub async fn run() -> anyhow::Result<()> {
    let service = RultraMcp::new().serve(rmcp::transport::stdio()).await?;
    service.waiting().await?;
    Ok(())
}

//! Rotating status pages on the 16x2 character LCD.
//!
//! # Why this reads from the snapshot
//!
//! The panel is refreshed from [`crate::state::latest`], never by sampling the
//! bus itself. A display that triggered its own sensor pass would make the
//! physical load a function of the refresh rate, and would drive the ultrasonic
//! every few seconds for the sake of showing a number.
//!
//! # Why an actuator write goes through a policy
//!
//! The LCD is an actuator, and this crate already learned once that an emitter
//! left in an undefined state is a problem you hear rather than see. The
//! refresh therefore holds an explicit grant for `ruv://lab/actuator/display`
//! and asks [`rultra_lab::Policy`] before every write. The grant's rate limit —
//! not a bare `sleep` — is what bounds how often the panel is touched, so a
//! future caller that refreshes from somewhere else inherits the same bound.
//!
//! # Honesty on a 16-character line
//!
//! A display has no room for provenance, which makes it the easiest place to
//! launder a bad reading into something authoritative-looking. Values from
//! sensors that are not trustworthy render as `--`. The range finder is
//! currently `Faulty` — it measures a floating pin — so it shows `--` rather
//! than a plausible distance.

use rultra_lab::{LabUri, MonoNanos, Policy};

/// Character columns on the panel. Anything longer is truncated by the
/// controller silently, so the renderer must do it deliberately instead.
pub const COLS: usize = 16;

/// How many distinct pages the rotation cycles through.
pub const PAGES: usize = 4;

/// Default seconds per page, and the range a caller may choose from.
pub const DEFAULT_SECS: u64 = 15;
pub const MIN_SECS: u64 = 5;
pub const MAX_SECS: u64 = 120;

// Compile-time, so an edit that makes the default unreachable or the floor
// fast enough to flicker fails the build rather than a test run.
const _: () = assert!(MIN_SECS <= DEFAULT_SECS && DEFAULT_SECS <= MAX_SECS);
const _: () = assert!(MIN_SECS >= 5);

/// The numbers a page may show. Every optional field means "no trustworthy
/// value", which is rendered as `--` rather than guessed at.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Stats {
    pub temp_c: Option<f64>,
    pub lux: Option<f64>,
    pub light_band: Option<&'static str>,
    /// `None` when the range finder is Faulty, which it currently is.
    pub range_cm: Option<f64>,
    pub devices_working: usize,
    pub devices_total: usize,
    pub witness_entries: usize,
    pub uptime_s: u64,
}

/// Pad or truncate to exactly the panel width.
fn fit(s: &str) -> String {
    let mut out: String = s.chars().take(COLS).collect();
    while out.chars().count() < COLS {
        out.push(' ');
    }
    out
}

/// Right-align a value in a labelled row, so digits do not jitter between
/// refreshes as the number of significant figures changes.
fn row(label: &str, value: &str) -> String {
    let label: String = label.chars().take(COLS).collect();
    let room = COLS.saturating_sub(label.chars().count());
    let value: String = value
        .chars()
        .rev()
        .take(room)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect();
    let pad = room - value.chars().count();
    fit(&format!("{label}{}{value}", " ".repeat(pad)))
}

fn num(v: Option<f64>, dp: usize, unit: &str) -> String {
    match v {
        Some(x) => format!("{x:.dp$}{unit}"),
        // The one string that must never be a number.
        None => "--".to_string(),
    }
}

fn uptime(secs: u64) -> String {
    let d = secs / 86_400;
    let h = (secs % 86_400) / 3600;
    let m = (secs % 3600) / 60;
    if d > 0 {
        format!("{d}d {h}h {m}m")
    } else if h > 0 {
        format!("{h}h {m}m")
    } else {
        format!("{m}m")
    }
}

/// Render one page as two exactly-`COLS`-wide lines.
pub fn render(s: &Stats, page: usize) -> (String, String) {
    match page % PAGES {
        0 => (
            row("rultra", &num(s.temp_c, 1, "C")),
            row("up", &uptime(s.uptime_s)),
        ),
        1 => (
            row("light", &num(s.lux, 0, "lx")),
            row("band", s.light_band.unwrap_or("--")),
        ),
        2 => (
            row(
                "devices",
                &format!("{}/{}", s.devices_working, s.devices_total),
            ),
            row("witness", &s.witness_entries.to_string()),
        ),
        _ => (
            row("range", &num(s.range_cm, 1, "cm")),
            // Says why, in the space available. A blank second line would read
            // as "nothing to report" rather than "this sensor is condemned".
            fit(if s.range_cm.is_none() {
                "sensor faulty"
            } else {
                ""
            }),
        ),
    }
}

/// Seconds per page, from `RULTRA_LCD_SECS`, clamped to a sane range.
pub fn interval_secs() -> u64 {
    std::env::var("RULTRA_LCD_SECS")
        .ok()
        .and_then(|s| s.parse::<u64>().ok())
        .unwrap_or(DEFAULT_SECS)
        .clamp(MIN_SECS, MAX_SECS)
}

/// The address this refresher drives.
pub fn display_uri() -> LabUri {
    LabUri::actuator("display", None)
}

/// A policy granting exactly this one actuator at the refresh rate.
///
/// Built here rather than passed in so the grant and the cadence cannot drift
/// apart: the rate limit *is* the refresh interval.
pub fn refresh_policy(secs: u64) -> Policy {
    Policy::new().grant(display_uri(), secs.saturating_mul(1_000_000_000))
}

/// Read the host's uptime in seconds.
pub fn host_uptime_s() -> u64 {
    std::fs::read_to_string("/proc/uptime")
        .ok()
        .and_then(|s| s.split('.').next().and_then(|n| n.parse().ok()))
        .unwrap_or(0)
}

/// Build the display stats from the current snapshot.
///
/// Applies the same trust rule the API does — a `Faulty` sensor contributes
/// nothing — so the panel and `/api/summary` can never disagree about whether
/// a reading is real.
pub fn stats_from_snapshot() -> Stats {
    use rultra_sense::{device, DeviceId, Verification};
    let snap = crate::state::latest();
    let verification = |id| {
        device::lookup(id)
            .map(|d| d.verification)
            .unwrap_or(Verification::Untested)
    };
    let lux = rultra_spatial::usable(
        crate::state::snap_scalar(&snap, DeviceId::Light),
        verification(DeviceId::Light),
    );
    Stats {
        temp_c: rultra_spatial::usable(
            crate::state::snap_scalar(&snap, DeviceId::CpuTemp),
            verification(DeviceId::CpuTemp),
        ),
        lux,
        light_band: lux.map(|l| match rultra_spatial::Light::from_lux(l) {
            rultra_spatial::Light::Dark => "dark",
            rultra_spatial::Light::Dim => "dim",
            rultra_spatial::Light::Lit => "lit",
            rultra_spatial::Light::Bright => "bright",
        }),
        range_cm: rultra_spatial::usable(
            crate::state::snap_scalar(&snap, DeviceId::Range),
            verification(DeviceId::Range),
        ),
        devices_working: device::CATALOG
            .iter()
            .filter(|d| d.verification == Verification::Working)
            .count(),
        devices_total: device::CATALOG.len(),
        witness_entries: std::fs::read_to_string(crate::state::state_dir().join("witness.jsonl"))
            .map(|t| t.lines().filter(|l| !l.trim().is_empty()).count())
            .unwrap_or(0),
        uptime_s: host_uptime_s(),
    }
}

/// Start the rotation. A no-op unless `RULTRA_LCD` is set to something other
/// than `off`, because the panel is `AcksButSilent` on this box and a refresher
/// nobody asked for would write to hardware every few seconds for no observable
/// benefit.
pub fn spawn() {
    if std::env::var("RULTRA_LCD")
        .unwrap_or_default()
        .eq_ignore_ascii_case("off")
    {
        return;
    }
    let secs = interval_secs();
    tokio::spawn(async move {
        let mut policy = refresh_policy(secs);
        let uri = display_uri();
        let start = std::time::Instant::now();
        let mut page = 0usize;
        loop {
            let now = MonoNanos(start.elapsed().as_nanos() as u64);
            if policy.permit(&uri, now).is_allowed() {
                let (l1, l2) = render(&stats_from_snapshot(), page);
                write_panel(l1, l2).await;
                page = page.wrapping_add(1);
            }
            tokio::time::sleep(std::time::Duration::from_secs(secs)).await;
        }
    });
}

#[cfg(all(target_os = "linux", feature = "hardware"))]
async fn write_panel(l1: String, l2: String) {
    // Off the async runtime: the HD44780 wake-up sequence sleeps ~60ms, which
    // would park a tokio worker on a four-core Pi.
    let _ = tokio::task::spawn_blocking(move || {
        if let Ok(b) = rultra_sense::backend::linux::LinuxBackend::open() {
            let _ = b.lcd_write(&l1, &l2);
        }
    })
    .await;
}

#[cfg(not(all(target_os = "linux", feature = "hardware")))]
async fn write_panel(_l1: String, _l2: String) {}
#[cfg(test)]
mod tests {
    use super::*;
    use rultra_lab::{Decision, DenyReason};

    fn full() -> Stats {
        Stats {
            temp_c: Some(72.15),
            lux: Some(231.6),
            light_band: Some("lit"),
            range_cm: None, // Faulty, as on the real box
            devices_working: 5,
            devices_total: 9,
            witness_entries: 257,
            uptime_s: 245_893,
        }
    }

    #[test]
    fn every_page_fits_the_panel_exactly() {
        for p in 0..PAGES {
            let (a, b) = render(&full(), p);
            assert_eq!(a.chars().count(), COLS, "page {p} line 1: {a:?}");
            assert_eq!(b.chars().count(), COLS, "page {p} line 2: {b:?}");
        }
    }

    #[test]
    fn a_long_value_is_truncated_rather_than_overflowing() {
        let s = Stats {
            witness_entries: 999_999_999_999,
            ..full()
        };
        let (a, b) = render(&s, 2);
        assert_eq!(a.chars().count(), COLS);
        assert_eq!(b.chars().count(), COLS);
    }

    #[test]
    fn a_condemned_sensor_shows_dashes_not_a_plausible_number() {
        // The whole point: 16 characters have no room for provenance, so an
        // untrustworthy value must not be displayed as if it were measured.
        let (l1, l2) = render(&full(), 3);
        assert!(l1.contains("--"), "range must render as dashes: {l1:?}");
        assert!(!l1.chars().any(|c| c.is_ascii_digit()), "no digits: {l1:?}");
        assert!(l2.contains("faulty"), "second line must say why: {l2:?}");
    }

    #[test]
    fn a_trustworthy_sensor_shows_its_value() {
        let s = Stats {
            range_cm: Some(120.0),
            ..full()
        };
        let (l1, l2) = render(&s, 3);
        assert!(l1.contains("120.0cm"), "{l1:?}");
        assert!(l2.trim().is_empty(), "no fault note when there is no fault");
    }

    #[test]
    fn missing_values_never_render_as_zero() {
        // Zero is a measurement. Absent is not.
        let s = Stats {
            temp_c: None,
            lux: None,
            light_band: None,
            ..Default::default()
        };
        let (a, _) = render(&s, 0);
        assert!(a.contains("--") && !a.contains('0'), "{a:?}");
        let (c, d) = render(&s, 1);
        assert!(c.contains("--"), "{c:?}");
        assert!(d.contains("--"), "{d:?}");
    }

    #[test]
    fn the_rotation_visits_every_page_then_repeats() {
        let seen: Vec<_> = (0..PAGES * 2).map(|i| render(&full(), i)).collect();
        assert_eq!(seen[0], seen[PAGES], "rotation must wrap");
        let distinct: std::collections::HashSet<_> = seen[..PAGES].iter().collect();
        assert_eq!(distinct.len(), PAGES, "pages must differ from each other");
    }

    #[test]
    fn uptime_reads_naturally_at_each_scale() {
        assert_eq!(uptime(245_893), "2d 20h 18m");
        assert_eq!(uptime(3_700), "1h 1m");
        assert_eq!(uptime(90), "1m");
    }

    #[test]
    fn the_grant_rate_limit_is_the_refresh_interval() {
        // If these could drift apart, the policy would stop bounding anything.
        let mut p = refresh_policy(15);
        let u = display_uri();
        assert!(p.permit(&u, MonoNanos::from_millis(0)).is_allowed());
        assert!(!p.permit(&u, MonoNanos::from_millis(14_999)).is_allowed());
        assert!(p.permit(&u, MonoNanos::from_millis(15_000)).is_allowed());
    }

    #[test]
    fn nothing_but_the_display_is_granted() {
        let mut p = refresh_policy(15);
        for other in ["ruv://lab/actuator/relay/1", "ruv://lab/actuator/buzzer"] {
            let u = LabUri::parse(other).unwrap();
            assert_eq!(
                p.permit(&u, MonoNanos(0)),
                Decision::Deny {
                    reason: DenyReason::NotGranted
                },
                "{other} must not be reachable from a display refresher"
            );
        }
    }
}

//! A deterministic in-memory backend.
//!
//! Exists so the unified surface is testable without a CrowPi attached. It is
//! deterministic rather than random: a test that fails must fail reproducibly.

use crate::{device, now, Backend, DeviceId, Presence, Reading, Value, Verification};
use std::collections::HashMap;

/// Scripted backend. Devices not explicitly present are reported absent.
#[derive(Debug, Default)]
pub struct MockBackend {
    present: HashMap<DeviceId, Value>,
    /// Incremented on every read, so successive reads differ predictably.
    tick: u64,
}

impl MockBackend {
    /// An empty board: nothing responds.
    pub fn empty() -> Self {
        Self::default()
    }

    /// A board mirroring what this project has actually verified on hardware.
    pub fn crowpi() -> Self {
        let mut b = Self::default();
        b.attach(
            DeviceId::Light,
            Value::Scalar {
                n: 58.3,
                unit: "lux".into(),
            },
        );
        b.attach(
            DeviceId::CpuTemp,
            Value::Scalar {
                n: 47.2,
                unit: "celsius".into(),
            },
        );
        b.attach(
            DeviceId::Range,
            Value::Scalar {
                n: 42.0,
                unit: "centimetre".into(),
            },
        );
        b.attach(DeviceId::Buttons, Value::Bool { on: false });
        b.attach(DeviceId::Tilt, Value::Bool { on: false });
        b
    }

    /// Make a device respond with `v`.
    pub fn attach(&mut self, id: DeviceId, v: Value) -> &mut Self {
        self.present.insert(id, v);
        self
    }
}

impl Backend for MockBackend {
    fn probe(&mut self) -> anyhow::Result<Vec<Presence>> {
        Ok(device::CATALOG
            .iter()
            .map(|d| {
                let responding = self.present.contains_key(&d.id);
                Presence {
                    device: d.id,
                    responding,
                    verification: d.verification,
                    detail: if responding {
                        format!("mock: {} responding", d.part)
                    } else {
                        format!("mock: {} absent", d.part)
                    },
                }
            })
            .collect())
    }

    fn read(&mut self, id: DeviceId) -> anyhow::Result<Reading> {
        let v = self
            .present
            .get(&id)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("{id:?} is not attached to this mock backend"))?;
        self.tick += 1;
        // Nudge scalars so consecutive reads are distinguishable but bounded.
        let value = match v {
            Value::Scalar { n, unit } => Value::Scalar {
                n: n + (self.tick % 3) as f64 * 0.1,
                unit,
            },
            other => other,
        };
        Ok(Reading {
            device: id,
            at: now(),
            value,
            verification: device::lookup(id)
                .map(|d| d.verification)
                .unwrap_or(Verification::Untested),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every variant must survive a JSON round-trip. A tagged enum accepts
    /// shapes at compile time that it cannot serialize at runtime, so this is
    /// checked rather than assumed.
    #[test]
    fn every_value_variant_round_trips_through_json() {
        for v in [
            Value::Scalar {
                n: 1.5,
                unit: "lux".into(),
            },
            Value::Bool { on: true },
            Value::Count { n: 7 },
        ] {
            let s = serde_json::to_string(&v).expect("must serialize");
            let back: Value = serde_json::from_str(&s).expect("must deserialize");
            assert_eq!(v, back);
        }
    }

    #[test]
    fn empty_board_reports_everything_absent() {
        let mut b = MockBackend::empty();
        let p = b.probe().unwrap();
        assert_eq!(p.len(), device::CATALOG.len());
        assert!(p.iter().all(|x| !x.responding));
    }

    #[test]
    fn reading_an_absent_device_errors_rather_than_fabricating() {
        let mut b = MockBackend::empty();
        assert!(b.read(DeviceId::Light).is_err());
    }

    #[test]
    fn crowpi_profile_reports_the_verified_devices() {
        let mut b = MockBackend::crowpi();
        let p = b.probe().unwrap();
        let up: Vec<_> = p
            .iter()
            .filter(|x| x.responding)
            .map(|x| x.device)
            .collect();
        assert!(up.contains(&DeviceId::Light));
        assert!(up.contains(&DeviceId::CpuTemp));
    }

    /// Probing must not launder an unverified device into a verified reading.
    #[test]
    fn probe_preserves_catalog_verification() {
        let mut b = MockBackend::crowpi();
        for p in b.probe().unwrap() {
            let cat = device::lookup(p.device).unwrap();
            assert_eq!(p.verification, cat.verification);
        }
    }

    #[test]
    fn successive_reads_differ_but_stay_bounded() {
        let mut b = MockBackend::crowpi();
        let a = b.read(DeviceId::Light).unwrap();
        let c = b.read(DeviceId::Light).unwrap();
        match (a.value, c.value) {
            (Value::Scalar { n: x, .. }, Value::Scalar { n: y, .. }) => {
                assert!((x - y).abs() < 1.0, "mock drifted too far: {x} vs {y}");
            }
            _ => panic!("expected scalars"),
        }
    }
}

//! A caching wrapper around any [`Backend`].
//!
//! # Why this exists
//!
//! Physical reads are expensive in wall-clock terms and the cost is fixed by
//! the parts, not the code: the BH1750 needs a 180ms one-shot conversion, and
//! an HC-SR04 read is a median of five bursts with the datasheet's 60ms
//! settling between them. Measured on this board, one pass over the sensors
//! costs about 460ms.
//!
//! The console polls every three seconds, the MCP server reads on demand, and
//! the cycle samples in windows. Without a cache each of those independently
//! fires the transducer, so a second viewer doubles the physical work for no
//! extra information — and an ultrasonic transducer driven continuously is
//! wear, not just latency.
//!
//! # The honest part
//!
//! A cached reading keeps the `at` of the moment it was **measured**, never the
//! moment it was served. A consumer comparing `at` to now sees the true age.
//! Restamping it would make a stale reading indistinguishable from a fresh one,
//! which is the same failure as presenting an unvalidated reading as a
//! measurement — the project's whole objection, one layer down.

use crate::{Backend, DeviceId, Presence, Reading};
use std::collections::HashMap;
use std::time::{Duration, Instant};

/// How long a reading stays fresh.
///
/// Chosen against the physics, not preference: one pass over the sensors costs
/// ~460ms, so a window shorter than that guarantees every request pays full
/// price and the cache does nothing. 1s is comfortably longer while staying
/// well inside the 3s console poll, so the displayed value is never more than
/// one poll behind the world.
pub const DEFAULT_TTL: Duration = Duration::from_millis(1000);

/// Wraps a backend and serves recent readings from memory.
pub struct CachingBackend<B: Backend> {
    inner: B,
    ttl: Duration,
    readings: HashMap<DeviceId, (Instant, Reading)>,
    presence: Option<(Instant, Vec<Presence>)>,
    hits: u64,
    misses: u64,
}

impl<B: Backend> CachingBackend<B> {
    /// Wrap with the default TTL.
    pub fn new(inner: B) -> Self {
        Self::with_ttl(inner, DEFAULT_TTL)
    }

    /// Wrap with an explicit TTL. A zero TTL disables caching entirely, which
    /// is the right setting for a measurement window that must sample the
    /// world rather than its own memory.
    pub fn with_ttl(inner: B, ttl: Duration) -> Self {
        Self {
            inner,
            ttl,
            readings: HashMap::new(),
            presence: None,
            hits: 0,
            misses: 0,
        }
    }

    /// Cache hits and misses since construction, for diagnostics.
    pub fn stats(&self) -> (u64, u64) {
        (self.hits, self.misses)
    }

    fn fresh<T>(&self, slot: &Option<(Instant, T)>) -> bool {
        slot.as_ref()
            .map(|(t, _)| t.elapsed() < self.ttl)
            .unwrap_or(false)
    }
}

impl<B: Backend> Backend for CachingBackend<B> {
    fn probe(&mut self) -> anyhow::Result<Vec<Presence>> {
        if self.fresh(&self.presence) {
            self.hits += 1;
            // Safe: `fresh` just confirmed it is populated.
            return Ok(self
                .presence
                .as_ref()
                .expect("fresh implies present")
                .1
                .clone());
        }
        self.misses += 1;
        let p = self.inner.probe()?;
        self.presence = Some((Instant::now(), p.clone()));
        Ok(p)
    }

    fn read(&mut self, id: DeviceId) -> anyhow::Result<Reading> {
        if let Some((t, r)) = self.readings.get(&id) {
            if t.elapsed() < self.ttl {
                self.hits += 1;
                // `at` is preserved from the original measurement on purpose.
                return Ok(r.clone());
            }
        }
        self.misses += 1;
        // A failed read is NOT cached: a sensor that has just come back would
        // otherwise stay "broken" for a full TTL, and an error is not an
        // observation worth remembering.
        let r = self.inner.read(id)?;
        self.readings.insert(id, (Instant::now(), r.clone()));
        Ok(r)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::backend::mock::MockBackend;
    use crate::{Value, Verification};

    /// A backend that counts physical reads, so the test measures avoided work
    /// rather than elapsed time.
    struct Counting {
        inner: MockBackend,
        reads: std::rc::Rc<std::cell::Cell<u32>>,
    }
    impl Backend for Counting {
        fn probe(&mut self) -> anyhow::Result<Vec<Presence>> {
            self.inner.probe()
        }
        fn read(&mut self, id: DeviceId) -> anyhow::Result<Reading> {
            self.reads.set(self.reads.get() + 1);
            self.inner.read(id)
        }
    }
    fn counting() -> (Counting, std::rc::Rc<std::cell::Cell<u32>>) {
        let c = std::rc::Rc::new(std::cell::Cell::new(0));
        (
            Counting {
                inner: MockBackend::crowpi(),
                reads: c.clone(),
            },
            c,
        )
    }

    #[test]
    fn repeated_reads_hit_the_hardware_once() {
        let (b, n) = counting();
        let mut c = CachingBackend::new(b);
        for _ in 0..10 {
            c.read(DeviceId::Light).unwrap();
        }
        assert_eq!(n.get(), 1, "ten reads should cost one physical read");
        assert_eq!(c.stats(), (9, 1));
    }

    #[test]
    fn different_devices_are_cached_independently() {
        let (b, n) = counting();
        let mut c = CachingBackend::new(b);
        c.read(DeviceId::Light).unwrap();
        c.read(DeviceId::CpuTemp).unwrap();
        c.read(DeviceId::Light).unwrap();
        assert_eq!(n.get(), 2, "one read each, then a hit");
    }

    #[test]
    fn an_expired_entry_is_refetched() {
        let (b, n) = counting();
        let mut c = CachingBackend::with_ttl(b, Duration::from_millis(1));
        c.read(DeviceId::Light).unwrap();
        std::thread::sleep(Duration::from_millis(5));
        c.read(DeviceId::Light).unwrap();
        assert_eq!(n.get(), 2);
    }

    /// The honesty property: a cached reading must not claim to be newer than
    /// the measurement it came from.
    #[test]
    fn a_cached_reading_keeps_its_original_timestamp() {
        let (b, _) = counting();
        let mut c = CachingBackend::new(b);
        let first = c.read(DeviceId::Light).unwrap();
        std::thread::sleep(Duration::from_millis(20));
        let second = c.read(DeviceId::Light).unwrap();
        assert_eq!(first.at, second.at, "serving must not restamp the reading");
        assert_eq!(first.value, second.value);
    }

    /// A zero TTL is the right setting for a measurement window, which must
    /// sample the world rather than its own memory.
    #[test]
    fn a_zero_ttl_disables_caching() {
        let (b, n) = counting();
        let mut c = CachingBackend::with_ttl(b, Duration::ZERO);
        for _ in 0..4 {
            c.read(DeviceId::Light).unwrap();
        }
        assert_eq!(n.get(), 4);
    }

    /// A sensor that has just recovered must not stay "broken" for a full TTL.
    #[test]
    fn failures_are_not_cached() {
        let (b, n) = counting();
        let mut c = CachingBackend::new(b);
        assert!(
            c.read(DeviceId::Matrix).is_err(),
            "actuator is not readable"
        );
        assert!(c.read(DeviceId::Matrix).is_err());
        assert_eq!(n.get(), 2, "an error must be retried, not remembered");
    }

    #[test]
    fn probe_is_cached_too() {
        let mut c = CachingBackend::new(MockBackend::crowpi());
        let a = c.probe().unwrap();
        let b = c.probe().unwrap();
        assert_eq!(a.len(), b.len());
        assert_eq!(c.stats().0, 1, "second probe should be a hit");
    }

    #[test]
    fn caching_preserves_verification() {
        let mut c = CachingBackend::new(MockBackend::crowpi());
        let r = c.read(DeviceId::Light).unwrap();
        assert_eq!(r.verification, Verification::Working);
        assert!(matches!(r.value, Value::Scalar { .. }));
    }
}
